import java.util.Arrays;

class PrimMST {

    private static final int INFINITY = Integer.MAX_VALUE;

    private static class Edge {
        final int from, to, weight;
        Edge(int from, int to, int weight) {
            this.from = from;
            this.to = to;
            this.weight = weight;
        }
    }

    private static int minKey(int[] key, boolean[] inMST)
    {
        int min = INFINITY;
        int minIndex = -1;

        for (int vertex = 0; vertex < inMST.length; vertex++) {
            if (!inMST[vertex] && key[vertex] < min) {
                min = key[vertex];
                minIndex = vertex;
            }
        }

        return minIndex;
    }

    private static Edge[] computeMST(int[][] graph)
    {
        int vertexCount = graph.length;

        int[] parent = new int[vertexCount];
        int[] key = new int[vertexCount];
        boolean[] inMST = new boolean[vertexCount];

        Arrays.fill(key, INFINITY);
        key[0] = 0;
        parent[0] = -1;

        for (int i = 0; i < vertexCount - 1; i++) {
            int current = minKey(key, inMST);
            if (current == -1) {
                break;
            }

            inMST[current] = true;

            for (int neighbor = 0; neighbor < vertexCount; neighbor++) {
                if (graph[current][neighbor] != 0 && !inMST[neighbor]
                    && graph[current][neighbor] < key[neighbor]) {
                    parent[neighbor] = current;
                    key[neighbor] = graph[current][neighbor];
                }
            }
        }

        Edge[] edges = new Edge[vertexCount - 1];
        for (int i = 1; i < vertexCount; i++) {
            edges[i - 1] = new Edge(parent[i], i, graph[parent[i]][i]);
        }
        return edges;
    }

    private static void printMST(Edge[] edges)
    {
        System.out.println("Edge \tWeight");
        int totalWeight = 0;
        for (Edge edge : edges) {
            System.out.println(edge.from + " - " + edge.to + "\t" + edge.weight);
            totalWeight += edge.weight;
        }
        System.out.println("Total weight: " + totalWeight);
    }

    public static void primMST(int[][] graph)
    {
        Edge[] edges = computeMST(graph);
        printMST(edges);
    }

    public static void main(String[] args)
    {
        int[][] graph = { { 0, 2, 0, 6, 0 },
                          { 2, 0, 3, 8, 5 },
                          { 0, 3, 0, 0, 7 },
                          { 6, 8, 0, 0, 9 },
                          { 0, 5, 7, 9, 0 } };

        primMST(graph);
    }
}

